@@ -10,12 +10,18 @@ namespace seed_a_backend.Api.Application;
 /// </summary>
 public class EventQueryService(AppDbContext db)
 {
-    public async Task<List<EventSummary>> GetEventSummariesAsync(CancellationToken ct = default) =>
-        await (
+    public async Task<List<EventSummary>> GetEventSummariesAsync(DateOnly? von, DateOnly? bis, CancellationToken ct = default)
+    {
+        var vonZeitpunkt = von?.ToDateTime(TimeOnly.MinValue);
+        var bisZeitpunkt = bis?.AddDays(1).ToDateTime(TimeOnly.MinValue);
+
+        return await (
             from e in db.Events
             join r in db.Rooms on e.RoomId equals r.Id
             join v in db.Venues on r.VenueId equals v.Id
+            where (vonZeitpunkt == null || e.Zeitpunkt >= vonZeitpunkt) && (bisZeitpunkt == null || e.Zeitpunkt < bisZeitpunkt)
             orderby e.Zeitpunkt, e.Id
             select new EventSummary(e.Id, e.Titel, v.Name, e.Zeitpunkt)
         ).ToListAsync(ct);
+    }
 }
